CREATE TABLE IF NOT EXISTS users ( username TEXT PRIMARY KEY, lname TEXT UNIQUE NOT NULL, pw_hash TEXT NOT NULL, salt TEXT NOT NULL, rating INTEGER NOT NULL DEFAULT 1200, peak INTEGER NOT NULL DEFAULT 1200, games INTEGER NOT NULL DEFAULT 0, wins INTEGER NOT NULL DEFAULT 0, losses INTEGER NOT NULL DEFAULT 0, draws INTEGER NOT NULL DEFAULT 0, created DOUBLE PRECISION NOT NULL, last_seen DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS rooms ( id TEXT PRIMARY KEY, white TEXT, black TEXT, white_guest INTEGER NOT NULL DEFAULT 0, black_guest INTEGER NOT NULL DEFAULT 0, state TEXT NOT NULL, status TEXT NOT NULL, rated INTEGER NOT NULL DEFAULT 1, private INTEGER NOT NULL DEFAULT 0, tc INTEGER NOT NULL DEFAULT 0, clock_w DOUBLE PRECISION NOT NULL DEFAULT 0, clock_b DOUBLE PRECISION NOT NULL DEFAULT 0, last_ts DOUBLE PRECISION NOT NULL DEFAULT 0, version INTEGER NOT NULL DEFAULT 0, created DOUBLE PRECISION NOT NULL, updated DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS games ( id TEXT PRIMARY KEY, mode TEXT NOT NULL, white TEXT NOT NULL, black TEXT NOT NULL, result TEXT NOT NULL, reason TEXT, score_w INTEGER NOT NULL, score_b INTEGER NOT NULL, moves TEXT NOT NULL, rating_w INTEGER, rating_b INTEGER, delta_w INTEGER, delta_b INTEGER, created DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS chat ( id TEXT PRIMARY KEY, room TEXT NOT NULL, author TEXT NOT NULL, body TEXT NOT NULL, ts DOUBLE PRECISION NOT NULL );
CREATE TABLE IF NOT EXISTS presence ( name TEXT PRIMARY KEY, ts DOUBLE PRECISION NOT NULL );
CREATE INDEX IF NOT EXISTS idx_games_white ON games(white);
CREATE INDEX IF NOT EXISTS idx_games_black ON games(black);
CREATE INDEX IF NOT EXISTS idx_chat_room ON chat(room);
CREATE INDEX IF NOT EXISTS idx_rooms_status ON rooms(status);
